<?php
require_once __DIR__.'/../includes/helpers.php'; require_role('admin'); $title=t('users.title');
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
  if($action==='save'){
    $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $role=in_array($_POST['role']??'',['admin','archaeologist','user'],true)?$_POST['role']:'user'; $status=in_array($_POST['status']??'',['active','inactive'],true)?$_POST['status']:'active'; $pass=$_POST['password']??'';
    if($id){
      if($pass!==''){ $hash=password_hash($pass,PASSWORD_DEFAULT); query('UPDATE ae_users SET name=?,email=?,role=?,status=?,password_hash=?,updated_at=NOW() WHERE id=?',[$name,$email,$role,$status,$hash,$id]); }
      else query('UPDATE ae_users SET name=?,email=?,role=?,status=?,updated_at=NOW() WHERE id=?',[$name,$email,$role,$status,$id]);
    }else{
      $hash=password_hash($pass?:'123456',PASSWORD_DEFAULT); query('INSERT INTO ae_users(name,email,password_hash,role,status,preferred_language) VALUES(?,?,?,?,?,?)',[$name,$email,$hash,$role,$status,current_lang()]);
    }
    flash('success',t('users.saved')); redirect('admin/users.php');
  }
  if($action==='toggle' && $id && $id!==current_user()['id']){
    $new=$_POST['new_status']==='inactive'?'inactive':'active'; query('UPDATE ae_users SET status=?,updated_at=NOW() WHERE id=?',[$new,$id]); flash('success',t('users.status_changed')); redirect('admin/users.php');
  }
}
$rows=fetch_all('SELECT id,name,email,phone,role,status,preferred_language,created_at FROM ae_users ORDER BY role,id');
include __DIR__.'/../includes/header.php';
?>
<section class="page-hero"><span class="eyebrow"><?= h(t('users.label')) ?></span><h1><?= h(t('users.title')) ?></h1><p><?= h(t('users.desc')) ?></p></section>
<div class="admin-site-toolbar"><div class="top-search-wrap" style="max-width:460px;flex:1"><i class="ti ti-search"></i><input class="form-control" data-live-filter="#usersTable" placeholder="<?= h(localized('ابحث بالاسم أو البريد أو الدور...','Search by name, email, or role...')) ?>"></div><button class="btn btn-primary" type="button" data-add-user data-title="<?= h(t('users.add')) ?>"><i class="ti ti-user-plus"></i><?= h(t('users.add')) ?></button></div>
<div class="table-card"><div class="table-responsive"><table class="table" id="usersTable"><thead><tr><th><?= h(t('profile.name')) ?></th><th><?= h(t('profile.email')) ?></th><th><?= h(t('profile.role')) ?></th><th><?= h(t('common.status')) ?></th><th><?= h(t('profile.joined')) ?></th><th><?= h(t('common.actions')) ?></th></tr></thead><tbody><?php foreach($rows as $r): $payload=['id'=>(int)$r['id'],'name'=>$r['name'],'email'=>$r['email'],'role'=>$r['role'],'status'=>$r['status']]; ?><tr data-filter-row><td><b><?= h($r['name']) ?></b></td><td class="ltr"><?= h($r['email']) ?></td><td><span class="badge badge-neutral"><?= h(role_label($r['role'])) ?></span></td><td><span class="badge badge-<?= $r['status']==='active'?'success':'danger' ?>"><?= h(status_label($r['status'])) ?></span></td><td><?= h(substr($r['created_at'],0,10)) ?></td><td class="actions"><button class="btn btn-muted btn-icon" type="button" data-edit-user data-title="<?= h(t('common.edit')) ?>" data-user="<?= h(json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>"><i class="ti ti-edit"></i></button><?php if((int)$r['id']!==current_user()['id']): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="new_status" value="<?= $r['status']==='active'?'inactive':'active' ?>"><button class="btn <?= $r['status']==='active'?'btn-danger':'btn-primary' ?>" type="submit"><?= h($r['status']==='active'?t('users.inactive'):t('users.active')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<template id="userFormTemplate"><div class="modal-head"><span class="eyebrow"><?= h(t('users.label')) ?></span><h2 data-modal-title><?= h(t('users.add')) ?></h2><p><?= h(t('users.desc')) ?></p></div><form id="userModalForm" method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id"><div class="form-grid"><div class="form-group full"><label class="form-label"><?= h(t('profile.name')) ?></label><input class="form-control" name="name" required></div><div class="form-group full"><label class="form-label"><?= h(t('profile.email')) ?></label><input class="form-control ltr" type="email" name="email" required></div><div class="form-group"><label class="form-label"><?= h(t('profile.role')) ?></label><select class="form-select" name="role"><option value="user"><?= h(t('role.user')) ?></option><option value="archaeologist"><?= h(t('role.archaeologist')) ?></option><option value="admin"><?= h(t('role.admin')) ?></option></select></div><div class="form-group"><label class="form-label"><?= h(t('common.status')) ?></label><select class="form-select" name="status"><option value="active"><?= h(t('users.active')) ?></option><option value="inactive"><?= h(t('users.inactive')) ?></option></select></div><div class="form-group full"><label class="form-label"><?= h(t('users.password')) ?></label><input class="form-control ltr" type="password" name="password" minlength="6"><span class="mini"><?= h(localized('اتركها فارغة عند التعديل للاحتفاظ بكلمة المرور الحالية.','Leave blank when editing to keep the current password.')) ?></span></div></div><div class="actions"><button class="btn btn-primary"><i class="ti ti-device-floppy"></i><?= h(t('common.save')) ?></button><button class="btn btn-light" type="button" data-modal-close><?= h(t('common.cancel')) ?></button></div></form></template>
<?php include __DIR__.'/../includes/footer.php'; ?>
